const row = $json;
const old = row.old_lead ?? {};
const allMessages = Array.isArray(row.messages) ? row.messages : [];

// 1. Regex bóc tách SĐT & Email
const allText = allMessages.map(m => m.text ?? '').join('\n');
const emailMatch = allText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const phoneMatches = allText.match(/(?:\+84|84|0)(?:[\s.\-]?\d){8,10}/g) ?? [];
function norm(v) {
  if (!v) return null;
  let p = v.replace(/[^\d+]/g, '');
  if (p.startsWith('+84')) p = '0' + p.slice(3);
  else if (p.startsWith('84')) p = '0' + p.slice(2);
  return p;
}
const regexPhone = phoneMatches.length ? norm(phoneMatches[0]) : null;
const regexEmail = emailMatch ? emailMatch[0].toLowerCase() : null;

// 2. Cắt gọn thông minh 40 tin nhắn gần nhất
const recentMessages = allMessages.slice(-40);
let conversation = recentMessages.map((m, i) => `${i + 1}. [${m.sender ?? 'KHÁCH'}]: ${m.text ?? ''}`).join('\n');
if (conversation.length > 8000) {
  conversation = '...(lược bớt hội thoại cũ)...\n' + conversation.slice(-8000);
}

const prompt = `Bạn là chuyên gia thẩm định & trích xuất khách hàng tiềm năng cho phần mềm CMS IntelliCAD.
Nhiệm vụ: Phân tích hội thoại, chấm điểm độ nóng của Lead (1 - 100) và xuất đúng định dạng JSON bên dưới.

TIÊU CHÍ CHẤM ĐIỂM LEAD (lead_score: 1 - 100) & PHÂN LOẠI (lead_tier):
- HOT (80 - 100): Có SĐT/Email rõ ràng, hỏi mua bản quyền cụ thể, cần báo giá gấp, hỏi phương thức thanh toán hoặc mua cho dự án công ty.
- WARM (50 - 79): Đang tìm hiểu tính năng CAD, hỏi giá sơ bộ, xin bản dùng thử, chưa để lại SĐT.
- COLD (1 - 49): Hỏi dạo, sinh viên xin tài liệu, spam, chào hàng quảng cáo, nhầm trang.

DỮ LIỆU CŨ HIỆN CÓ:
- Tên: ${old.full_name ?? 'null'}
- SĐT: ${old.phone ?? 'null'}
- Email: ${old.email ?? 'null'}
- Công ty: ${old.company ?? 'null'}
- Nhu cầu: ${old.need ?? 'null'}
- Số lượng: ${old.requested_quantity ?? 'null'}

SĐT trích xuất từ regex: ${regexPhone ?? 'null'}
Email trích xuất từ regex: ${regexEmail ?? 'null'}

HỘI THOẠI KHÁCH HÀNG:
${conversation || '(Không có nội dung)'}

ĐỊNH DẠNG JSON BẮT BUỘC:
{
  "product": "CMS IntelliCAD",
  "customer_name": "Tên khách hoặc null",
  "phone": "Số điện thoại hoặc null",
  "email": "Email hoặc null",
  "company": "Tên công ty hoặc null",
  "customer_type": "Cá nhân | Doanh nghiệp | Chưa xác định",
  "quantity": 1,
  "need": "Tóm tắt nhu cầu cụ thể",
  "request_quote": true,
  "lead_score": 85,
  "lead_tier": "HOT",
  "lead_summary": "Khách cần 3 key cho công ty xây dựng, đã để lại SĐT",
  "confidence": 0.95
}`;

return {
  json: {
    conversation_id: row.conversation_id,
    external_user_id: row.external_user_id,
    channel_account_id: row.channel_account_id,
    platform: row.platform,
    page_id: row.page_id,
    conversation_link: row.conversation_link,
    last_message_at: row.last_message_at,
    old_lead: old,
    fb_customer_name: row.fb_customer_name || '',
    regex_phone: regexPhone,
    regex_email: regexEmail,
    ai_payload: {
      model: "qwen3-vl-30b",
      messages: [
        { "role": "system", "content": "Bạn là chuyên gia thẩm định Lead bán hàng B2B. Luôn trả lời bằng định dạng JSON thuần túy, không giải thích." },
        { "role": "user", "content": prompt }
      ],
      temperature: 0.1,
      max_tokens: 1000
    }
  }
};

const response = $json;
const source = $('Build AI Request').item.json;
const old = source.old_lead ?? {};

let rawContent = response.choices?.[0]?.message?.content ?? '';
let cleanJson = rawContent.trim();
if (cleanJson.startsWith('```')) {
  cleanJson = cleanJson.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
}

let ai = {};
try {
  ai = JSON.parse(cleanJson);
} catch (e) {
  ai = {
    customer_name: null,
    phone: source.regex_phone,
    email: source.regex_email,
    company: null,
    customer_type: 'Chưa xác định',
    quantity: null,
    need: null,
    request_quote: false,
    lead_score: (source.regex_phone ? 75 : 40),
    lead_tier: (source.regex_phone ? 'HOT' : 'WARM'),
    lead_summary: 'Trích xuất tự động qua Regex',
    confidence: 0.0
  };
}

const pref = (n, o) => (n === null || n === undefined || n === '') ? (o ?? null) : n;
const customerName = pref(ai.customer_name, old.full_name) || source.fb_customer_name || 'Khách Facebook';
const phone = pref(ai.phone ?? source.regex_phone, old.phone);
const email = pref(ai.email ?? source.regex_email, old.email);
const company = pref(ai.company, old.company);
const quantity = pref(ai.quantity, old.requested_quantity);
const need = pref(ai.need, old.need);

let customerType = ['Cá nhân', 'Doanh nghiệp'].includes(ai.customer_type) ? ai.customer_type : (old.customer_type === 'personal' ? 'Cá nhân' : (old.customer_type === 'business' ? 'Doanh nghiệp' : 'Chưa xác định'));
const requestQuote = Boolean(ai.request_quote || old.quote_status);

let quotationStatus = old.quote_status ?? 'CHƯA BÁO GIÁ';
if (quotationStatus === 'CHƯA BÁO GIÁ' && requestQuote) {
  quotationStatus = 'ĐANG XỬ LÝ';
}

let leadStatus = old.lead_status ?? 'new';
if ((phone || email) && need) {
  leadStatus = 'qualified';
}

let score = Number(ai.lead_score ?? 50);
if (phone && score < 75) score = 80;
let tier = String(ai.lead_tier || (score >= 80 ? 'HOT' : (score >= 50 ? 'WARM' : 'COLD'))).toUpperCase();
const isHot = tier === 'HOT' || score >= 80;

const now = new Date().toISOString();

return {
  json: {
    conversation_id: source.conversation_id,
    external_user_id: source.external_user_id,
    customer_name: customerName,
    phone: phone,
    email: email,
    company: company,
    customer_type: customerType,
    quantity: quantity,
    need: need,
    product: 'CMS IntelliCAD',
    request_quote: requestQuote,
    lead_status: leadStatus,
    quotation_status: quotationStatus,
    quote_code: old.request_code ?? null,
    conversation_link: source.conversation_link,
    last_contact_at: source.last_message_at ?? now,
    lead_score: score,
    lead_tier: tier,
    lead_summary: ai.lead_summary || '',
    is_hot_lead: isHot,
    extraction_confidence: Number(ai.confidence ?? 0.8)
  }
};

const x = $json;
const s = $('Merge + Build Full 21 Fields').item.json;

const tierPrefix = s.lead_tier === 'HOT' ? '🔥 HOT' : (s.lead_tier === 'WARM' ? '⚡ WARM' : '❄️ COLD');
const statusDisplay = `${tierPrefix} (${s.lead_score}/100) - ${(x.status ?? s.lead_status ?? "NEW").toUpperCase()}`;

return {
  json: {
    "Mã báo giá": x.quote_code ?? s.quote_code ?? null,
    "Nguồn lead": "Facebook",
    "Sản phẩm": "CMS IntelliCAD",
    "Tên khách hàng": x.full_name ?? s.customer_name ?? null,
    "Số điện thoại": x.phone ?? s.phone ?? null,
    "Email": x.email ?? s.email ?? null,
    "Công ty": x.company ?? s.company ?? null,
    "Loại khách hàng": s.customer_type ?? "Chưa xác định",
    "Số lượng": x.requested_quantity ?? s.quantity ?? null,
    "Nhu cầu": x.need ?? s.need ?? null,
    "Trạng thái lead": statusDisplay,
    "Trạng thái báo giá": (x.quotation_status ?? s.quotation_status ?? "CHƯA BÁO GIÁ").toUpperCase(),
    "Nhân viên phụ trách": null,
    "Lần liên hệ gần nhất": x.last_contacted_at ?? s.last_contact_at ?? null,
    "Lịch liên hệ tiếp theo": null,
    "Ghi chú nhân viên": s.lead_summary || null,
    "Link hội thoại": s.conversation_link ?? null,
    "Ngày tạo lead": new Date().toISOString(),
    "Cập nhật lần cuối": new Date().toISOString(),
    "Cập nhật DB": new Date().toISOString(),
    "Trạng thái đồng bộ": "PENDING",
    // Trường phụ trợ thông báo
    "is_hot_lead": s.is_hot_lead,
    "lead_score": s.lead_score,
    "lead_tier": s.lead_tier
  }
};

